<template><div class="app-container" v-loading="loading"><h3>询盘保留与数据审计</h3><el-alert title="保留期默认0（不限期）。这里只会按明确确认的预览手动清理，每批最多100条；不会自动擦除。历史私有备份另按备份保留策略管理。" :closable="false"/>
 <el-form label-width="130px" style="max-width:850px;margin-top:16px" @submit.prevent><el-form-item label="无活动保留天数"><el-input-number v-model="days" :min="0" :max="3650" :precision="0"/><span> 0表示不限；按提交、处理、改派或跟进中的最后活动计算。</span></el-form-item><el-form-item label="适用状态"><el-checkbox-group v-model="statuses"><el-checkbox label="已处理" value="DONE"/><el-checkbox label="垃圾留言" value="SPAM"/><el-checkbox label="待处理（慎选）" value="NEW"/></el-checkbox-group></el-form-item><el-form-item label="变更原因"><el-input v-model="reason" maxlength="300" placeholder="填写设置保留策略的原因"/></el-form-item><el-form-item><el-button v-hasPermi="['cms:data:edit']" type="primary" :loading="busy" @click="save">保存保留策略</el-button><el-button @click="loadPolicy">重新读取</el-button></el-form-item></el-form>
 <template v-if="canClean"><el-divider>清理预览</el-divider><p>当前已保存：{{policy?.retentionDays||0}}天；状态 {{(policy?.statuses||[]).map(s=>labels[s]).join('、')}}。表单未保存内容不会用于预览。</p><el-input v-model="cleanReason" maxlength="300" placeholder="本次手动清理的原因" style="max-width:500px"/><el-button :disabled="!policy?.retentionDays" :loading="busy" @click="preview">生成预览</el-button>
 <template v-if="batch"><el-alert :title="`预览 #${batch.batchId}，符合条件共${batch.totalEligible}条，本批${batch.previewCount}条；有效期至${batch.expiresAt}，状态${batch.status}`" :closable="false"/><el-table :data="items"><el-table-column prop="inquiryId" label="询盘" width="90"/><el-table-column prop="name" label="称呼"/><el-table-column prop="contact" label="联系方式（遮蔽）"/><el-table-column prop="activeAt" label="最后活动" width="170"/><el-table-column label="版本"><template #default="s">预览 {{s.row.sourceVersion}} / 当前 {{s.row.currentVersion}}<el-tag v-if="s.row.sourceVersion!==s.row.currentVersion" type="danger">已变化</el-tag></template></el-table-column></el-table><pagination v-if="itemTotal" :total="itemTotal" v-model:page="ipg.pageNum" v-model:limit="ipg.pageSize" @pagination="loadItems"/><el-button type="danger" :disabled="batch.status!=='PREVIEWED'||!batch.previewCount" :loading="busy" @click="execute">确认清理此预览</el-button></template>
 <el-divider>我的预览与执行记录</el-divider><el-table :data="batches"><el-table-column prop="batchId" label="批次" width="90"/><el-table-column prop="status" label="状态" width="120"/><el-table-column prop="previewCount" label="预览行数"/><el-table-column prop="erasedCount" label="已擦除行数"/><el-table-column prop="expiresAt" label="预览截止" width="170"/><el-table-column label="操作"><template #default="s"><el-button link @click="select(s.row)">查看此批</el-button></template></el-table-column></el-table><pagination v-if="batchTotal" :total="batchTotal" v-model:page="bpg.pageNum" v-model:limit="bpg.pageSize" @pagination="loadBatches"/></template>
 <template v-if="canAudit"><el-divider>数据操作审计</el-divider><el-table :data="events"><el-table-column prop="eventId" label="记录" width="80"/><el-table-column prop="action" label="动作" width="100"/><el-table-column prop="createBy" label="操作者" width="110"/><el-table-column prop="rowCount" label="行数" width="90"/><el-table-column prop="createTime" label="时间" width="170"/><el-table-column prop="details" label="筛选/原因（无客户原文）" show-overflow-tooltip/><el-table-column prop="fileSha256" label="文件SHA256" show-overflow-tooltip/></el-table><pagination v-if="eventTotal" :total="eventTotal" v-model:page="epg.pageNum" v-model:limit="epg.pageSize" @pagination="loadEvents"/></template>
 </div></template>
<script setup>
import{ref,reactive,onMounted,onBeforeUnmount,onDeactivated,onActivated}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{workflow}from'@/api/cms/workflow';import auth from '@/plugins/auth'
const canClean=auth.hasPermi('cms:data:cleanup'),canAudit=auth.hasPermi('cms:data:audit'),policy=ref(),days=ref(0),statuses=ref(['DONE','SPAM']),reason=ref(''),cleanReason=ref(''),batch=ref(),items=ref([]),itemTotal=ref(0),batches=ref([]),batchTotal=ref(0),events=ref([]),eventTotal=ref(0),busy=ref(false),loading=ref(false),bpg=reactive({pageNum:1,pageSize:10}),ipg=reactive({pageNum:1,pageSize:10}),epg=reactive({pageNum:1,pageSize:10}),labels={NEW:'待处理',DONE:'已处理',SPAM:'垃圾留言'};let epoch=0,resume=false
async function loadPolicy(){const n=epoch,r=await workflow('data/policy');if(n===epoch){policy.value=r.data;days.value=r.data.retentionDays;statuses.value=[...r.data.statuses];reason.value=''}}
async function loadBatches(){if(!canClean)return;const n=epoch,r=await workflow('data/cleanup/list','get',undefined,{...bpg});if(n===epoch){batches.value=r.rows;batchTotal.value=r.total;if(batch.value)batch.value=r.rows.find(b=>b.batchId===batch.value.batchId)||batch.value}}
async function loadEvents(){if(!canAudit)return;const n=epoch,r=await workflow('data/events','get',undefined,{...epg});if(n===epoch){events.value=r.rows;eventTotal.value=r.total}}
async function load(){const n=++epoch;loading.value=true;try{await Promise.all([loadPolicy(),loadBatches(),loadEvents()])}finally{if(n===epoch)loading.value=false}}
async function save(){if(busy.value)return;if(!reason.value.trim()||!statuses.value.length){ElMessage.warning('请选择状态并填写变更原因');return};busy.value=true;try{await workflow('data/policy','put',{version:policy.value.version,retentionDays:days.value,statuses:statuses.value,reason:reason.value});batch.value=null;ElMessage.success('策略已保存，没有清理数据');await load()}finally{busy.value=false}}
async function preview(){if(busy.value)return;if(!cleanReason.value.trim()){ElMessage.warning('请填写本次清理原因');return};const n=epoch;busy.value=true;try{const r=await workflow('data/cleanup/preview','post',{reason:cleanReason.value});if(n!==epoch)return;await select(r.data);await loadBatches();await loadEvents();ElMessage.success('预览已生成，尚未擦除数据')}finally{busy.value=false}}
async function select(b){batch.value=b;ipg.pageNum=1;await loadItems()}
async function loadItems(){if(!batch.value)return;const n=epoch,r=await workflow(`data/cleanup/${batch.value.batchId}/items`,'get',undefined,{...ipg});if(n===epoch){items.value=r.rows;itemTotal.value=r.total}}
async function execute(){if(busy.value)return;const n=epoch,b={...batch.value};try{const p=await ElMessageBox.prompt(`将不可恢复地擦除本批${b.previewCount}条询盘的联系人、正文、备注及跟进文字，并取消提醒。请输入“确认清除”。`,'确认手动清理',{inputPattern:/^确认清除$/,inputErrorMessage:'必须完整输入确认清除',confirmButtonText:'确认清除',type:'warning'});if(n!==epoch)return;busy.value=true;await workflow(`data/cleanup/${b.batchId}/execute`,'post',{version:b.version,confirmation:p.value});ElMessage.success('此批已清理');await loadBatches();await loadItems();await loadEvents()}catch{}finally{busy.value=false}}
function close(){++epoch;batch.value=null;items.value=[];reason.value='';cleanReason.value=''}onMounted(load);onBeforeUnmount(close);onDeactivated(()=>{resume=true;close()});onActivated(()=>{if(resume){resume=false;load()}})
</script>
